    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following interventions is specifically prohibited by a "Do Not Intubate" (DNI) order?', '["Chest compressions", "Insertion of an endotracheal tube", "Administration of epinephrine", "Oxygen via nasal cannula"]', 1, 'A DNI order specifically refuses invasive mechanical ventilation (intubation), though non-invasive options like CPAP or BiPAP may still be allowed depending on the specifics.'),
    (v_topic_id, 'A patient is a "DNR." They are found choking on a piece of food. Should the nurse perform the Heimlich maneuver?', '["No, they are a DNR", "Yes, a DNR order typically applies to cardiac or respiratory arrest from natural disease progression, not to treatable, acute choking or accidents", "Only if the doctor is there", "None of the above"]', 1, 'DNR status does not mean "Do Not Treat" for reversible, non-arrest emergencies.'),
    (v_topic_id, 'What is the "Success Rate" (survival to discharge) for in-hospital CPR in an elderly patient with multiple comorbidities?', '["90%", "50%", "Approximately 10-15% (or less depending on the specific condition)", "0%"]', 2, 'Realistic expectations of CPR success are crucial for informed consent; for many chronically ill patients, the success rate is very low.'),
    (v_topic_id, 'The "POLST" (Physician Orders for Life-Sustaining Treatment) form is primarily intended for which patient population?', '["All healthy adults", "Patients with a serious illness or advanced frailty whose provider would not be surprised if they died within the next year", "Only pediatric patients", "None of the above"]', 1, 'POLST is for the "seriously ill," whereas standard advance directives are for all adults.'),
    (v_topic_id, 'If a patient has both a "POLST" and a "Living Will" that conflict, which is typically prioritized in an emergency?', '["The Living Will", "The POLST (as it is a current medical order signed by a clinician)", "Neither", "The oldest document"]', 1, 'POLST forms are actionable medical orders designed for immediate implementation by clinicians and EMS.'),
    (v_topic_id, 'Can a nurse or physician be sued for "Battery" if they perform CPR on a patient with a known, valid DNR order?', '["No, they are trying to help", "Yes, performing an invasive medical procedure against a patient''s explicit, valid refusal is legally battery", "Only if the patient dies", "None of the above"]', 1, 'Respecting the right to refuse care (Autonomy) is a legal requirement; "Wrongful Resuscitation" is an emerging area of litigation.'),
    (v_topic_id, 'What does a "Limited Code" usually mean?', '["Do everything for 10 minutes", "A specific list of allowed vs. disallowed interventions (e.g., ''Meds and shocks only, no intubation'')", "Only the family can do CPR", "None of the above"]', 1, 'Limited codes allow patients to tailor their resuscitation preferences.'),
    (v_topic_id, 'A patient arrives in the ER with a "DNR" tattoo on their chest. What is the standard medical response?', '["Honor the tattoo immediately", "Begin resuscitation while attempting to find a valid medical order or surrogate, as tattoos are not legally binding medical documents and their intent can be ambiguous", "Ignore it forever", "Ask the tattoo artist"]', 1, 'While tattoos are suggestive, they do not meet the legal requirements of an advance directive or medical order. Resuscitate until clarity is achieved.'),
    (v_topic_id, 'In the operating room, a "DNR" is often "suspended" because:', '["Surgeons hate DNRs", "Some arrests in the OR are expected, transient, and easily reversible consequences of anesthesia/surgery", "Insurance requires it", "None of the above"]', 1, 'Required reconsideration allows for a nuanced plan during high-risk procedures.'),
    (v_topic_id, 'What is a "Chemical Code"?', '["A code using only toxic gases", "Resuscitation using only ACLS medications, avoiding chest compressions and intubation", "A code in a chemistry lab", "None of the above"]', 1, 'Some patients opt for "Meds only," though the efficacy of medications without compressions is extremely low.'),
    (v_topic_id, 'A "MOLST" form is usually signed by:', '["Only the patient", "A physician, nurse practitioner, or physician assistant AND the patient or surrogate", "A lawyer", "The hospital chaplain"]', 1, 'MOLST/POLST forms require a clinician''s signature to turn patient preferences into actionable orders.'),
    (v_topic_id, 'Can a "Surrogate" sign a DNR for a patient?', '["No, only the patient can", "Yes, if the patient lacks capacity and the surrogate believes it aligns with the patient''s wishes or best interests", "Only if a judge agrees", "None of the above"]', 1, 'Surrogates have the power to make EOL decisions, including code status.'),
    (v_topic_id, 'What is "Medical Futility" (or Inappropriate Care) in resuscitation?', '["When the doctor is tired", "When there is a near-certainty that CPR will not restore the patient to a meaningful life or even achieve physiological survival", "When the patient is old", "None of the above"]', 1, 'Futility is a controversial but important ethical concept regarding the limits of medical intervention.'),
    (v_topic_id, 'A "Unilateral DNR" is an order written by a physician:', '["After talking to the patient", "Without the consent of the patient or family, based on the determination that CPR would be futile (only allowed in very specific institutional policies and some jurisdictions)", "By mistake", "None of the above"]', 1, 'Unilateral DNRs are highly regulated and often require a multi-physician review or ethics committee approval.'),
    (v_topic_id, 'Does a DNR order mean "Do Not Hospitalize"?', '["Yes, always", "No, a DNR only refers to care at the time of arrest; a patient can still be hospitalized for other treatments", "Only if it is a ''Comfort Care Only'' order", "None of the above"]', 1, 'DNR is limited to resuscitation.'),
    (v_topic_id, 'What is the role of "EMS" (Emergency Medical Services) regarding a Living Will in the field?', '["They must read it and follow it", "They generally cannot follow a Living Will and must provide full treatment unless they see a state-approved DNR order or POLST", "They ignore everything", "None of the above"]', 1, 'Living Wills are not designed for the "fast-paced" EMS environment; POLST and out-of-hospital DNRs are.'),
    (v_topic_id, 'A "Slow Code" is ethically considered:', '["A good compromise", "Deceptive and a violation of the physician-patient relationship", "Standard practice in the ICU", "None of the above"]', 1, 'Slow codes violate the principle of veracity (truth-telling).'),
    (v_topic_id, 'Which of the following is a "Reversible" cause of cardiac arrest where CPR might be highly successful?', '["End-stage metastatic cancer", "Anesthesia-induced arrhythmia or acute electrolyte imbalance in a previously healthy person", "Advanced multi-organ failure", "None of the above"]', 1, 'Understanding "reversibility" is key to ethical code status discussions.'),
    (v_topic_id, 'A patient is a "DNR" but develops a sudden, treatable pneumothorax. Should the doctor place a chest tube?', '["No, they are a DNR", "Yes, because a chest tube is a treatment for a specific condition, not a resuscitation attempt for cardiac arrest", "Only if the family agrees", "None of the above"]', 1, 'Treating a complication is not the same as resuscitating an arrest.'),
    (v_topic_id, 'What is "Wrongful Resuscitation"?', '["A medical error where the wrong drug was given", "A legal claim brought when a patient is resuscitated against their clear and documented wishes", "Performing CPR on the wrong patient", "None of the above"]', 1, 'This is a growing legal concern emphasizing the importance of honoring refusals.'),
    (v_topic_id, 'Which of the following is TRUE about the "POLST" form?', '["It is a legal document, not a medical order", "It is intended to be used across all care settings (home, nursing home, hospital)", "It is only valid for 30 days", "None of the above"]', 1, 'The portability of POLST is its greatest advantage.'),
    (v_topic_id, 'If a patient is a "Full Code" but the doctor knows it won''t work, what is the best ethical approach?', '["Ignore the ''Full Code'' status", "Provide the resuscitation but discuss the prognosis and goals of care with the family as soon as possible, or before the arrest occurs", "Sue the family", "None of the above"]', 1, 'While difficult, the default is to follow the patient''s status while vigorously pursuing "Goals of Care" conversations.'),
    (v_topic_id, 'Which of the following is a "Psychological" benefit of a DNR order for the family?', '["It saves money", "It relieves the family of the burden of making a ''death-inducing'' decision in the heat of a crisis", "It means they don''t have to visit", "None of the above"]', 1, 'Clear orders provide clarity and peace of mind during a crisis.'),
    (v_topic_id, 'A patient with a "DNR" order arrests. The family suddenly screams, "Do everything! Save him!" What should the physician do?', '["Do everything", "Ideally, follow the DNR while providing compassionate support to the family, though in some high-conflict ''real world'' situations, physicians may feel compelled to begin resuscitation until the situation can be stabilized and discussed", "Run away", "None of the above"]', 1, 'While the DNR is legally valid, the "emotional override" by family is a classic ethical dilemma that requires calm leadership.'),
    (v_topic_id, 'What is the "First Link" in the chain of survival for out-of-hospital arrest?', '["Defibrillation", "Early recognition and calling 911", "Intubation", "Adrenaline"]', 1, 'Education on EOL care also involves educating on when NOT to call 911 (if the patient is in hospice).'),
    (v_topic_id, 'A patient is a "DNI" but is currently in respiratory distress. Is "CPAP" (Non-invasive ventilation) allowed?', '["No", "Yes, unless the patient specifically refused non-invasive ventilation as well", "Only if they have insurance", "None of the above"]', 1, 'DNI specifically means no endotracheal tube.'),
    (v_topic_id, 'Which of the following is a "Goal" of a family meeting regarding code status?', '["To force a DNR", "To align the clinical reality with the patient''s and family''s values and goals", "To show the doctor is in charge", "None of the above"]', 1, 'Alignment and understanding are the goals, not a specific outcome.'),
    (v_topic_id, 'A "Purple" or "Bright Green" form in many states indicates:', '["The patient has no insurance", "A state-approved out-of-hospital medical order (like POLST or DNR)", "The patient is a celebrity", "None of the above"]', 1, 'High-visibility colors help EMS identify the forms quickly.'),
    (v_topic_id, 'The "Texas Advance Directives Act" is famous for:', '["Banning DNRs", "Providing a legal process for doctors to withdraw life-sustaining treatment they deem inappropriate, even over family objection, after a 10-day notice and ethics review", "Legalizing PAS", "None of the above"]', 1, 'This is a key example of state law addressing medical futility.'),
    (v_topic_id, 'Which of the following is TRUE regarding CPR in "Advanced Dementia"?', '["It is highly successful", "It rarely results in survival to discharge and often leads to significant rib fractures and trauma without clinical benefit", "It cures the dementia", "None of the above"]', 1, 'Frailty is a major predictor of poor CPR outcomes.'),
    (v_topic_id, 'A "DNR" order in a patient''s chart must be written by:', '["The nurse", "A physician (or sometimes NP/PA depending on state law)", "The patient", "The social worker"]', 1, 'It is a medical order.'),
    (v_topic_id, 'Can a "DNR" order be verbal?', '["No, never", "Yes, in some emergency settings, a physician can give a verbal DNR order to the nursing staff, though it must be co-signed as soon as possible", "Only if recorded", "None of the above"]', 1, 'Verbal orders are for acute situations.'),
    (v_topic_id, 'What is the "Default" code status in a US hospital?', '["DNR", "Full Code", "No care", "None of the above"]', 1, 'Unless specified otherwise, every patient is a Full Code.'),
    (v_topic_id, 'Which of the following is a "Physical" complication of CPR?', '["Rib fractures", "Sternal fractures", "Internal organ damage", "All of the above"]', 3, 'Informing families of the "violence" of CPR is part of honest counseling.'),
    (v_topic_id, 'A patient with a "DNR" order wants "Antibiotics" for a UTI. Is this appropriate?', '["No", "Yes, if the goal is to treat the UTI and improve comfort/function, as a DNR only applies to cardiac arrest", "Only if they pay cash", "None of the above"]', 1, 'DNR does not exclude other treatments.'),
    (v_topic_id, 'What is "Post-Cardiac Arrest Syndrome"?', '["A type of flu", "The complex physiological response and potential neurological damage that occurs after a patient is successfully resuscitated", "A feeling of being tired", "None of the above"]', 1, 'Resuscitation is only the first step in a very difficult recovery.'),
    (v_topic_id, 'A "POLST" form must be reviewed:', '["Never", "When the patient is transferred between facilities or when their health status significantly changes", "Every morning", "None of the above"]', 1, 'Regular review ensures the orders remain relevant.'),
    (v_topic_id, 'Which of the following is NOT a part of the "SPIKES" protocol?', '["Strategy", "Invitation", "Knowledge", "Surgical Risk Assessment"]', 3, 'SPIKES is for bad news, not pre-op assessment.'),
    (v_topic_id, 'A patient is a "DNR" but is currently "Hypotensive" (low blood pressure). Should the nurse give a bolus of IV fluids?', '["No", "Yes, unless the patient''s overall goals of care exclude fluids (fluids are not part of resuscitation from arrest)", "Only if they are thirsty", "None of the above"]', 1, 'Managing blood pressure is not CPR.'),
    (v_topic_id, 'What is the role of the "Hospital Chaplain" in code status discussions?', '["To pray for a DNR", "To support the family''s spiritual and existential needs during a difficult decision", "To sign the form", "None of the above"]', 1, 'Chaplains are part of the interdisciplinary palliative team.'),
    (v_topic_id, 'A "DNAR" order stands for:', '["Do Not Attempt Resuscitation", "Do Not Ask Regarding care", "Doctor Not Always Right", "None of the above"]', 0, 'DNAR is often preferred over DNR to emphasize that resuscitation is an *attempt* that may not succeed.'),
    (v_topic_id, 'Which of the following is TRUE about DNR for "Minors"?', '["Parents cannot sign one", "Parents can sign a DNR for their child if it is in the child''s best interest and aligns with the goals of palliative care", "Children must be 18 to have one", "None of the above"]', 1, 'Parental authority includes the right to limit non-beneficial, burdensome care.'),
    (v_topic_id, 'A "DNR" patient arrests. The family says, "We haven''t said goodbye yet, please just do it for 5 minutes." The physician should:', '["Comply", "Explain that ''short'' CPR is clinically ineffective and violates the patient''s documented wishes, while offering to let them be with the patient in their final moments", "Tell them to leave", "None of the above"]', 1, 'Managing grief without violating autonomy is the core challenge here.'),
    (v_topic_id, 'What is the "Survival rate" for unwitnessed out-of-hospital arrest?', '["50%", "25%", "Less than 5%", "100%"]', 2, 'Out-of-hospital arrest has a very poor prognosis, making advance planning even more vital.'),
    (v_topic_id, 'A "POLST" form is categorized as a:', '["Legal directive", "Medical order", "Recommendation", "None of the above"]', 1, 'Its status as a medical order gives it immediate authority.'),
    (v_topic_id, 'Can a physician refuse to write a "DNR" that the patient wants?', '["Yes, always", "No, if a competent patient requests a DNR, it is a refusal of future treatment that MUST be honored", "Only if the patient is young", "None of the above"]', 1, 'Autonomy includes the right to refuse resuscitation.'),
    (v_topic_id, 'Which of the following is a "Barrier" to having a code status discussion?', '["Lack of time", "Fear of taking away hope", "The physician''s own discomfort with death", "All of the above"]', 3, 'Recognizing these barriers is the first step to overcoming them.'),
    (v_topic_id, 'What is "Anticipatory Guidance"?', '["Predicting the future", "Preparing the patient/family for what to expect during the dying process or a future crisis", "Giving advice on taxes", "None of the above"]', 1, 'Preparing families for the "noisy breathing" or "mottling" of death is essential.'),
    (v_topic_id, 'A "DNR" order can be rescinded by:', '["The patient at any time", "The nurse", "The patient''s neighbor", "None of the above"]', 0, 'A competent patient has the final word.'),
    (v_topic_id, 'Which of the following describes the "Success" of CPR?', '["The patient woke up", "The patient had a ''Return of Spontaneous Circulation'' (ROSC), even if they never left the hospital", "The patient went home with their previous level of function", "Both B and C are used to define success in different contexts"]', 3, 'Clarifying what "success" means (ROSC vs. Survival to Discharge) is vital for honest discussions.')
